-- Drosophila melanogaster safe-harbor / attP landing-site batch 1.
-- Two source families:
--  (a) The 3 "flagship" phiC31 attP docking sites (attP2, attP40, ZH-attP-86Fb),
--      read directly from the primary paper's full text (Bischof et al. 2007,
--      PMID 17360644, PMC1805588) -- confidence = high, reviewed = true. Only
--      cytological bands are given for these (no bp coordinates were extracted),
--      so genome_build is left null -- bands are assembly-independent, a build
--      label would add nothing here.
--  (b) 32 VK docking sites from the P[acman] BAC transgenesis platform
--      (Venken et al. 2006, PMID 17008526, Science 314:1747-1751), coordinates
--      taken from the official P[acman] resource site (flypush.research.bcm.edu/
--      pacmanfly/docking.php). genome_build = 'dm3' -- this is a known, definite
--      fact (P[acman] predates the dm6/BDGP6 assembly entirely, released 2014),
--      not a hedge or uncertainty, so it is recorded plainly rather than left
--      null. Confidence = high: the coordinate source (official project
--      resource page) is as reliable as coordinate data gets. The one exception
--      is VK00029, kept at 'low' -- that is a distinct, real biological
--      caveat (heterochromatic location, a classic silencing-prone context),
--      unrelated to genome-build certainty.
--
-- Unlike mammalian entries, Drosophila attP/VK sites are germline transgenesis
-- tools (whole-organism, not a specific differentiated tissue), so
-- tissue_context reflects that rather than a specific cell type.

insert into public_safe_harbors_staging
  (species, genome_build, coords, locus_name, evidence_summary, confidence, stability, tissue_context, source_pmid, source_title, reviewed, approved)
values

('Drosophila', null, null, 'attP2',
 'Cytological location 68A4, chromosome 3L, inserted in the 5'' UTR of Mocs1. One of the two most widely used phiC31 docking sites in the field (alongside attP40), used extensively for LexA driver and TRIP/RNAi transgenic lines. In the original characterization, transformation frequency using injected integrase mRNA never exceeded 7%, but rose to up to 30% (and 69% with a codon-optimized integrase source) once an endogenous germline-expressed vas-phiC31 source was used -- the docking site itself did not change, only the delivery method. No repression or ectopic expression of a lacZ reporter was observed, indicating no strong nearby enhancers/repressors under standard assay conditions.',
 'high', 'Widely reused across hundreds of published transgenic lines; no report of site-specific silencing under standard germline transgenesis use', 'Whole organism / germline (fly transgenesis; not tissue-restricted). Some tissue-specific silencing effects reported in later literature specifically for attP40, not attP2 -- see attP40 record.', '17360644', 'An optimized transgenesis system for Drosophila using germ-line-specific phiC31 integrases', true, false),

('Drosophila', null, null, 'attP40',
 'Cytological location 25C, chromosome 2L, located within intron 1 of several msp-300 transcript isoforms (upstream of others). One of the two most widely used phiC31 docking sites (alongside attP2), especially for GAL4-driven TRIP/RNAi lines. IMPORTANT CAVEAT found in later literature (not in the original 2007 paper): because attP40 sits inside msp-300 (a nesprin/KASH-domain gene important for nuclear positioning and muscle function), transgene insertions here have been shown to act as insertional mutations of msp-300 and to measurably affect phenotypes in msp-300-dependent tissues (e.g. muscle, and glomerular organization of Or47b olfactory receptor neurons) -- i.e. this "safe harbor" has a documented, tissue-specific safety caveat that attP2 does not share.',
 'high', 'Reused across many lines, but NOT tissue-neutral -- documented insertional effects on msp-300-dependent phenotypes', 'Caveat is tissue-specific: affects muscle (msp-300/nesprin function) and olfactory receptor neuron (Or47b glomerular) phenotypes specifically; effect not generic across all tissues.', '17360644', 'An optimized transgenesis system for Drosophila using germ-line-specific phiC31 integrases', true, false),

('Drosophila', null, 'chr3R:7,634,080-7,634,081', 'ZH-attP-86Fb',
 'Cytological region 86F, chromosome 3R, within the 5'' intron of the two longer isoforms of the chloride channel-a gene (ClC-a / CG31116). The best-performing line from the original 68-line screen: highest transformation frequency (25%) of all candidates tested with injected integrase mRNA, well above the ~7%-or-less ceiling seen with attP2 under the same delivery method. One of 25 lines selected because they are both homozygous viable and intergenically (or, in this case, intronically but non-disruptively) located.',
 'high', 'Best transformation efficiency (25%) of the original screen; homozygous viable', 'Whole organism / germline (fly transgenesis; not tissue-restricted).', '17360644', 'An optimized transgenesis system for Drosophila using germ-line-specific phiC31 integrases', true, false),

('Drosophila', 'dm3', 'chr2R:23,236,182-23,236,183', 'VK00001', 'P[acman] BAC-transgenesis docking site, cytological location 59D3. Coordinate from the official P[acman] project resource page -- a reliable primary source for docking-site coordinates, even though the site has not been individually benchmarked for silencing/methylation the way the mammalian catalog entries have.', 'high', 'Standard, reusable docking site; widely used, no individual silencing/methylation benchmark exists (unlike mammalian entries)', 'Whole organism / germline (fly transgenesis; not tissue-restricted).', '17008526', 'P[acman]: a BAC transgenic platform for targeted insertion of large DNA fragments in D. melanogaster', true, false),
